    let mut words: Vec<(String, usize)> = Vec::new();
    let mut counts: HashMap<String, usize> = HashMap::new();

    // Convert to lowercase and split into words (Unicode-aware, using split_whitespace and Unicode)
    for word in text.split_whitespace() {
        let lower_word = word.to_lowercase();
        if let Some(chars) = lower_word.chars().filter(|c| c.is_alphabetic()).collect() {
            let clean_word = chars.join("");
            if !clean_word.is_empty() {
                *counts.entry(clean_word).or_insert(0) += 1;
            }
        }
    }

    // Build result vector: sort by frequency descending, then alphabetically ascending
    let mut result = counts.into_iter().collect::<Vec<_>>();
    result.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    result
}
