fn eval_rpn(expr: &str) -> Result<i64, String> {
    let tokens = expr.split_whitespace().filter_map(|s| s.parse().ok());
    let mut stack: Vec<i64> = Vec::new();

    for token in tokens {
        match token {
            // Operadores binarios
            "+" | "-" | "*" | "/" => {
                if stack.len() >= 2 {
                    let b = stack.pop().unwrap();
                    let a = stack.pop().unwrap();
                    match token {
                        "+" => stack.push(a + b),
                        "-" => stack.push(a - b),
                        "*" => stack.push(a * b),
                        "/" => {
                            if b == 0 {
                                return Err("division by zero".to_string());
                            }
                            stack.push(a / b)
                        }
                    }
                } else {
                    // Missing operand
                    return Err(format!("not enough operands for operator {}", token));
                }
            }
            // Numbers (including negative)
            n if n.parse::<i64>().is_ok() => {
                stack.push(n.parse().unwrap());
            }
            _ => {
                // Invalid token
                return Err(format!("invalid token: {}", token));
            }
        }
    }

    // After processing all tokens, there should be exactly one value on the stack
    if stack.len() != 1 {
        if stack.len() > 1 {
            // Too many values left
            return Err(format!("extra operands at the end: {:?}", stack));
        } else {
            // Only one value? That's fine, but we need to check if it's a valid result.
