fn mat_mul(a: &[Vec<f64>], b: &[Vec<f64>]) -> Option<Vec<Vec<f64>>> {
    // Check dimensions: a has rows = len(a), cols = len(a[0])
    // b has rows = len(b), cols = len(b[0])
    // For multiplication a * b, we need len(a).0 == len(b)
    // and for each row i in a, len(a[i]) == len(b).0
    if a.is_empty() {
        return Some(vec![vec![0.0]; a.len().next().unwrap().len()]); // empty matrix? handle edge case
    }

    let a_rows = a.len();
    let a_cols = a[0].len();
    let b_rows = b.len();
    let b_cols = b[0].len();

    // Check compatibility: a's cols must equal b's rows
    if a_cols != b_rows {
        return None;
    }

    // Also check each row in a has same length (a_cols) and each row in b has same length (b_cols)
    // We already checked a[0].len() = a_cols, but need to ensure all rows in a have a_cols elements
    // and all rows in b have b_cols elements
    for row in a {
        if row.len() != a_cols {
            return None;
        }
    }
    for row in b {
        if row.len() != b_cols {
            return None;
        }
    }

    // Initialize result matrix: a * b has dimensions a_rows x b_cols
    let mut result = vec![vec![0.0; b_cols]; a_rows];

    // Perform multiplication
    for i in 0..a_rows {
        for j in 0..b_cols {
            let mut sum = 0.0;
            for k in 0..a_cols {
                sum += a[i][k] * b[k][j];
            }
            result[i][j] = sum;
        }
    }

    Some(result)
}
