use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

fn shortest_path(n: usize, edges: &[(usize, usize, u32)], src: usize, dst: usize) -> Option<u32> {
    // Build adjacency list: for each node, a vector of (neighbor, weight)
    let mut adj: HashMap<usize, Vec<(usize, u32)>> = HashMap::new();
    for &(u, v, w) in edges {
        adj.entry(u).or_insert_with(Vec::new).push((v, w));
    }

    // Initialize distances: src = 0, others = u32::MAX (infinity)
    let mut dist = vec![u32::MAX; n];
    dist[src] = 0;

    // Priority queue: min-heap based on distance (BinaryHeap stores Reverse<(u32, usize)>, where first is distance, second is node)
    let mut heap = BinaryHeap::new();
    heap.push(Reverse((0, src)));

    while let Some(Reverse((current_dist, u))) = heap.pop().unwrap() {
        // If we've already found a shorter path to u, skip
        if current_dist > dist[u] {
            continue;
        }

        // Process neighbors
        if let Some(neighbors) = adj.get(&u) {
            for &(v, w) in neighbors {
                let new_dist = dist[u].saturating_add(w);
                if new_dist < dist[v] {
                    dist[v] = new_dist;
                    heap.push(Reverse((new_dist, v)));
                }
            }
        }
    }

    // Return the distance to dst if reachable, else None
    if dist[dst] == u32::MAX {
        None
    } else {
        Some(dist[dst])
    }
}
